from lib import *
S = SS('k97')
F1 = [['kubectl create secret docker-registry', ''], ['type', 'kubernetes.io/dockerconfigjson'], ['.dockerconfigjson', 'auths → localhost:5000'], ['auth 字段', 'base64(用户名:密码)']]
F2 = [['无 secret', '探测无 Authorization → 401'], ['有 secret', '再带 Authorization: Basic puller:s3cret'], ['结果', 'nosecret: no basic auth credentials'], ['withsecret', '认证通过 → not found']]
F3 = [['default SA 加 imagePullSecrets', ''], ['新建 Pod 不写', ''], ['准入补入 spec.imagePullSecrets', 'regcred'], ['认证通过', 'not found']]
F4 = [['auths 键写错服务器', '凭证不发给 localhost:5000'], ['密码错', '401 Unauthorized'], ['引用别的命名空间的 secret', '被忽略,no basic auth credentials']]
PANELS = [('f', 'flow', '拉取凭证'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
steps = [
    step("kubectl create secret docker-registry regcred --docker-server=localhost:5000 --docker-username=puller --docker-password=s3cret:type 是 kubernetes.io/dockerconfigjson,data 只有一个键 .dockerconfigjson;解码后是 {auths: {localhost:5000: {username, password, email, auth}}},auth 字段是 base64(\"用户名:密码\") = cHVsbGVyOnMzY3JldA==,解码得 puller:s3cret。", f=fl(F1, cur=[2, 3], done=[0, 1]), t=tl(S(1), mark=lidx(S(1), 'type=', '解码后的'), done=lidx(S(1), 'auth 字段')), kv=KV([['dockerconfigjson', '和 ~/.docker/config.json 同一种格式'], ['auth', '只是 base64,不是加密(见 k58)'], ['按仓库地址分键', 'auths 里每个 server 一份凭证']], ['dockerconfigjson'])),
    step("假仓库要求 Basic 认证 puller:s3cret。两个 Pod 拉 localhost:5000/team/app:1.0:仓库收到 5 个请求,其中 3 个没有 Authorization 头(运行时先不带凭证探测,收到 401 + WWW-Authenticate 才带凭证重来),2 个带 Authorization,解码是 puller:s3cret。nosecret 的 Pod 失败原因:pull access denied, repository does not exist or may require authorization: authorization failed: no basic auth credentials;withsecret(spec.imagePullSecrets=[regcred])失败原因变成 localhost:5000/team/app:1.0: not found——认证通过了,这个镜像确实不存在。", f=fl(F2, cur=[0, 1], done=[2, 3]), t=tl(S(2), mark=lidx(S(2), '仓库收到', 'nosecret Pod'), done=lidx(S(2), 'withsecret Pod', 'Pod spec 里')), kv=KV([['先探测再认证', '先无凭证请求,401 之后才带凭证'], ['报错变了就说明凭证被接受', '从 401 变成 not found'], ['kubelet 只传凭证', '认证由运行时和仓库完成']], ['报错变了'])),
    step("给 default ServiceAccount 加上 imagePullSecrets: [regcred]:新建的 Pod viasa 没写 imagePullSecrets,但 spec.imagePullSecrets 已经是 [{name: regcred}]——ServiceAccount 准入把它补进来了;拉取 localhost:5000/team/app:2.0 同样认证通过,失败原因是 not found。", f=fl(F3, cur=[2], done=[0, 1, 3]), t=tl(S(3), mark=lidx(S(3), '给 default ServiceAccount'), done=lidx(S(3), 'viasa:')), kv=KV([['SA 上配一次', '这个命名空间里的新 Pod 都自动带上'], ['已有的 Pod', '不会被改,准入只处理新建'], ['常见做法', '每个命名空间的 default SA 配好私有仓库凭证']], ['SA 上配一次'])),
    step("几种“凭证没起作用”的情形:secret 的 auths 键写成 registry.other.com,镜像在 localhost:5000 —— 仍是 no basic auth credentials(地址不匹配,凭证不发给它);地址对但密码错 —— 401 Unauthorized;命名空间 k97b 的 Pod 引用 k97 里的 regcred —— Pod 照样创建成功,但拉取失败 no basic auth credentials(imagePullSecrets 只能引用同命名空间的 secret,引用不到会被忽略)。", f=fl(F4, cur=[0, 1, 2]), t=tl(S(4), mark=lidx(S(4), 'secret 的 auths 键', '地址对但密码错', '命名空间 k97b'), done=lidx(S(4), '事件')), kv=KV([['地址要完全匹配', 'auths 的键和镜像里的仓库地址一致'], ['同命名空间', 'secret 不能跨命名空间引用'], ['静默忽略', '引用不到不会报错,只能从拉取失败看出来']], ['同命名空间'])),
]
A = mkartk('k97', 97, 'Kubernetes,imagePullSecrets,私有仓库,dockerconfigjson,ServiceAccount,真实验证,动画演示',
    '用一个要求 Basic 认证的假仓库实测 imagePullSecrets:kubernetes.io/dockerconfigjson 的 auths 里 auth 就是 base64(用户名:密码);没有 secret 时仓库只收到不带 Authorization 的请求并报 no basic auth credentials,有 secret 时运行时先探测、收到 401 再带上 puller:s3cret,报错变成 not found(认证通过);给 default ServiceAccount 配置后新 Pod 自动带上;auths 的服务器地址写错、密码错、跨命名空间引用 secret 都会失败。',
    '私有仓库的凭证是怎么交给运行时的?Secret 里到底存了什么?ServiceAccount 上配置 imagePullSecrets 有什么用?为什么 Pod 引用了 secret 还是拉取失败?这篇用一个会记录 Authorization 头的假仓库,把每一步看清楚。',
    [('401 → not found', '带上正确的 imagePullSecrets 后,拉取失败的原因从认证失败变成“镜像不存在”,说明凭证被仓库接受'), ('3 + 2', '一次拉取里仓库收到的请求:3 个不带 Authorization 的探测,2 个带凭证'), ('同命名空间', 'imagePullSecrets 只能引用与 Pod 同命名空间的 Secret;引用不到会被静默忽略')],
    [('Secret 的内容', '<p><code>kubectl create secret docker-registry regcred --docker-server=localhost:5000 --docker-username=puller --docker-password=s3cret</code>:<code>type</code> 是 <code>kubernetes.io/dockerconfigjson</code>,<code>data</code> 只有一个键 <code>.dockerconfigjson</code>;解码后是 <code>{"auths": {"localhost:5000": {username, password, email, auth}}}</code>,<code>auth</code> 字段是 <code>base64("用户名:密码")</code> —— <code>cHVsbGVyOnMzY3JldA==</code>,解码得 <code>puller:s3cret</code>。这和 Secret 一样只是编码,不是加密(见 k58)。</p>'),
     ('凭证如何用上', '<p>假仓库要求 Basic 认证 <code>puller:s3cret</code>。两个 Pod 拉 <code>localhost:5000/team/app:1.0</code>:仓库收到 5 个请求,其中 3 个没有 <code>Authorization</code> 头(运行时先不带凭证探测,收到 401 + <code>WWW-Authenticate</code> 才带凭证重来),2 个带了,解码是 <code>puller:s3cret</code>。<code>nosecret</code> 失败原因是 <code>pull access denied, repository does not exist or may require authorization: authorization failed: no basic auth credentials</code>;<code>withsecret</code>(<code>spec.imagePullSecrets=[regcred]</code>)失败原因变成 <code>localhost:5000/team/app:1.0: not found</code>——认证通过了,这个镜像本来就不存在。报错从 401 变成 not found,就是凭证被接受的证据。</p>'),
     ('用 ServiceAccount 统一配置', '<p>给 <code>default</code> ServiceAccount 加上 <code>imagePullSecrets: [regcred]</code>:新建的 Pod <code>viasa</code> 没写 <code>imagePullSecrets</code>,但 <code>spec.imagePullSecrets</code> 已经是 <code>[{name: regcred}]</code>——ServiceAccount 准入把它补进来了,拉取 <code>localhost:5000/team/app:2.0</code> 同样认证通过。(只处理新建的 Pod,已有的不会被改。)</p>'),
     ('凭证没起作用的几种情形', '<p>secret 的 <code>auths</code> 键写成 <code>registry.other.com</code>,镜像在 <code>localhost:5000</code>:仍是 <code>no basic auth credentials</code>,凭证不会发给地址不匹配的仓库;地址对但密码错:<code>401 Unauthorized</code>;命名空间 <code>k97b</code> 的 Pod 引用 <code>k97</code> 里的 <code>regcred</code>:Pod 照样创建成功,但拉取失败 <code>no basic auth credentials</code>——<code>imagePullSecrets</code> 只能引用同命名空间的 Secret,引用不到会被忽略,排查时要从拉取失败的原因倒推。</p>')],
    steps,
    [ENV_K + '。三节点 kind 集群 kx-main(Kubernetes v1.37.0,containerd v2.3.4);假仓库是 worker 上的 hostNetwork Pod(python http.server),要求 Basic 认证,containerd 通过 /etc/containerd/certs.d/localhost:5000/hosts.toml 用 HTTP 访问它;认证通过后对不存在的镜像返回 404;请求头由假仓库逐条打印;每种情形各一次',
     '没有验证:Bearer token 认证的完整流程(401 + realm 获取令牌);kubelet 凭证提供者插件(credential provider,云上 ECR/GCR 用);节点本地 config.json 里的凭证;同一个仓库配置多个 secret 时的选择顺序;镜像真正拉取成功的情形(假仓库不提供镜像);imagePullSecrets 对 initContainers 的适用'],
    'imagePullSecrets', PANELS)
